@js:
let url = `https://m.newqy.com/user/search.html?q=${encodeURIComponent(key)}`;
let html = "";
try {
    html = String(java.ajax(url));
} catch (e) {}

// 提取所有script标签中的var声明
let code = "";
let scriptMatches = html.match(/<script[^>]*>([\s\S]*?)<\/script>/gi);
if (scriptMatches) {
    for (let match of scriptMatches) {
        let content = match.replace(/<script[^>]*>/gi, "").replace(/<\/script>/gi, "");
        if (content.includes("var ") && content.includes("search")) {
            code += content;
        }
    }
}

// 安全执行JS，提取搜索数据
let searchData = [];
try {
    eval(code);
    // 兼容该站所有可能的变量名
    if (typeof data !== "undefined" && data.search && Array.isArray(data.search)) {
        searchData = data.search;
    } else if (typeof list !== "undefined" && Array.isArray(list)) {
        searchData = list;
    } else if (typeof result !== "undefined" && result.data && result.data.search) {
        searchData = result.data.search;
    }
} catch (e) {}

// 返回Legado标准格式，永远不会返回undefined
JSON.stringify({"data": {"search": searchData}});
